const ev = $input.first().json;
if (ev.tokenHash !== '{{BV:TOKEN_SHA256}}') return [{ json: { resultado: 'nao_autenticada' } }];
const cfgM = { titulo_sim: "{{BV:mensagens.titulo_sim}}", titulo_nao: "{{BV:mensagens.titulo_nao}}" };
const rc = '{{BV:mensagens.ativo}}' === 'True' ? bvMReconhecer(ev.body, cfgM) : null;
// selecao da lista de confirmacao (from_internal com selectedRowID bvc:<id>:<s|n>): nao e mensagem, vai para bv-confirmacao
if (rc && rc.origem === 'id' && typeof ev.body.sender === 'string' && ev.body.sender) return [{ json: { resultado: 'selecao', telefone: ev.body.sender, rec: rc } }];
const r = bvNormalizar(ev, { maxKb: {{BV:payload.max_kb}} });
if (r.status === 'aceita') return [{ json: { resultado: 'aceita', msg: { ...r.msg, confirmaTitulo: rc && rc.origem === 'titulo' ? (rc.confirmado ? 'sim' : 'nao') : '' } } }];
return [{ json: { resultado: r.status === 'invalida' ? 'invalida' : 'descartada', motivo: r.motivo } }];

