const minha = $('Inserir mensagem').first().json;
const ult = $('Ler ultima').first().json.ultima;
const agora = Date.now();
const idade = $input.first().json.mais_antiga_ms;
const entregar = deveEntregar({ ultimaId: ult == null ? '' : ult, minhaId: minha.id, maisAntigaMs: idade == null ? agora : Number(idade), agoraMs: agora, tetoS: {{BV:buffer.teto_s}} });
return [{ json: { entregar, inicioMs: agora } }];

