const linhas = $input.all().map(i => i.json).filter(j => j.id != null);
if (!linhas.length) return [{ json: { vazio: true } }];
const ord = consolidar(linhas);
return [{ json: { vazio: false, turno_id: ord[0].turno_id, contato_id: $('Inserir mensagem').first().json.contato_id,
  telefone: $('Normalizar').first().json.msg.telefone, total: ord.length,
  itens: ord.map(l => ({ mensagem_id: Number(l.id), tipo: l.tipo, conteudo: l.conteudo, midia_url: l.midia_url, midia_mime: l.midia_mime, midia_segundos: l.midia_segundos == null ? null : Number(l.midia_segundos), midia_bytes: l.midia_bytes == null ? null : Number(l.midia_bytes), recebida_em: new Date(l.criado_em).toISOString() })) } }];

